//! Whole passive noscript clones retain actual nodes and exact raw text.
use super::*;
fn fixture(raw:bool,attrs:&str)->(Document,Forms,Page){
 let source=format!("<body><noscript id=fallback {attrs}><img id=fake src=missing><script>window.bad=1;</script>&amp;</noscript><div id=mount></div><p id=out>Real</p>");
 let mut d=if raw{crate::html::parse_loaded_document_with_scripting(&source,true,&||Ok(())).unwrap()}else{crate::html::parse(&source)};d.scripting_enabled=true;
 if raw{let host=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("fallback")).unwrap();let child=d.nodes[host].children[0];let mut units="<img id=fake src=missing><script>window.bad=1;</script>&amp;".encode_utf16().collect::<Vec<_>>();units.extend([0xdfff,0xd800]);d.nodes[child].kind=NodeKind::Text(DomString::from_units(&units,4096).unwrap());}
 let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-clone.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)
}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn noscript_host_clone_deep_shallow_exact_text_actual_identity_and_passive_connection(){
 let(mut d,mut f,mut p)=fixture(true,"");run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('fallback'),old=host.firstChild,raw=old.data,mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});var shallow=host.cloneNode(false),copy=host.cloneNode(true);if(shallow===host||copy===host||copy===shallow||shallow.ownerDocument!==document||copy.ownerDocument!==document||shallow.parentNode!==null||copy.parentNode!==null||shallow.childNodes.length||copy.firstChild===old||copy.firstChild.parentNode!==copy||copy.firstChild.nodeType!==3||copy.firstChild.data!==raw||copy.textContent!==raw||copy.innerHTML!==raw||raw.charCodeAt(raw.length-2)!==57343||raw.charCodeAt(raw.length-1)!==55296||copy.id!=='fallback'||shallow.id!=='fallback'||watch.takeRecords().length)throw 'independent raw clone';var imported=document.importNode(host,true);if(imported===host||imported===copy||imported.firstChild===old||imported.firstChild===copy.firstChild||imported.firstChild.parentNode!==imported||imported.ownerDocument!==document||imported.parentNode!==null||imported.textContent!==raw||imported.id!=='fallback'||watch.takeRecords().length)throw 'same owner import delegates exact clone';copy.id='copy';shallow.id='shallow';mount.appendChild(copy);mount.appendChild(shallow);var records=watch.takeRecords();if(document.getElementById('copy')!==copy||document.getElementById('shallow')!==shallow||host.id!=='fallback'||copy.firstChild.data!==raw||records.length!==2||records[0].addedNodes[0]!==copy||records[1].addedNodes[0]!==shallow||document.getElementById('fake')!==null||document.querySelectorAll('script').length||window.bad!==undefined)throw 'passive clone connection';mount.removeChild(copy);if(copy.firstChild.data!==raw||copy.firstChild.parentNode!==copy||watch.takeRecords()[0].removedNodes[0]!==copy)throw 'retired clone identity';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_host_clone_nontext_and_protected_attribute_guards_remain_atomic(){
 for(raw,attrs)in[(false,""),(true,"onclick='window.bad=2'"),(true,"is='fake-widget'")]{let(mut d,mut f,mut p)=fixture(raw,attrs);run(&mut d,&mut f,&mut p,"var host=document.getElementById('fallback');");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let error=p.runtime.execute("host.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Cloning this element"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(window.bad!==undefined||document.getElementById('fake')!==null)throw 'protected source unchanged';document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());}
}
#[test]
fn noscript_host_clone_quota_refusals_publish_nothing_then_recover(){
 let(mut d,mut f,mut p)=fixture(true,"");run(&mut d,&mut f,&mut p,"var host=document.getElementById('fallback'),old=host.firstChild,watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let error=p.runtime.execute("host.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();let e=error.to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||watch.takeRecords().length)throw 'clone refusal atomic';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"var copy=host.cloneNode(true);if(copy.firstChild===old||copy.firstChild.data!==old.data||copy.ownerDocument!==document||watch.takeRecords().length)throw 'fresh clone recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
